  return <><AsideHeader className=\"app-shell\" compact={compact} onChangeCompact={setCompact} collapseTitle=\"Свернуть меню\" expandTitle=\"Развернуть меню\" hideSectionDividers logo={{text: 'orbit', icon: BrandMark, iconSize: 31, textSize: 27, className: 'app-logo', onClick: () => setSection('home')}} aboveMenuContent={<div className={"'`sidebar-intro ${compact ? '"'compact' : ''}"'`}>{!compact && <><Button className="workspace-switch" view="outlined" size="xl" width="max" onClick={() => setSection('"'settings')}><span className=\"shop-avatar\"><ShoppingBag width={18}/></span><span className=\"shop-info\"><strong>{shopName}</strong><small>Рабочее пространство</small></span><Icon data={ChevronDown} size={13}/></Button><span className=\"nav-caption\">УПРАВЛЕНИЕ</span></>}</div>} menuItems={[{id: 'home', title: 'Главная', icon: House}, {id: 'users', title: 'Пользователи', icon: Persons}, {id: 'orders', title: 'Заказы', icon: ShoppingBag, rightAdornment: "'!compact ? <span className="nav-count">{orders.length}</span> : undefined}, {id: '"'settings', title: 'Настройки', icon: Gear}].map(item => ({...item, current: section === item.id, className: 'nav-item', onItemClick: () => {setSection(item.id); setSearch('');}}))} renderFooter={() => <div className={"'`sidebar-footer ${compact ? '"'compact' : ''}"'`}>{!compact && <div className="help-card"><span className="help-card-icon"><CircleQuestion width={19}/></span><strong>Всегда на связи</strong><p>Поможем разобраться<br/>с любым вопросом</p><Button view="outlined" size="m" width="max" onClick={() => setModal('"'help')}>Связаться с поддержкой<Icon data={ArrowUpRight} size={13}/></Button></div>}<Button className=\"sidebar-help\" view=\"flat\" width=\"max\" onClick={() => setModal('help')}><Icon data={CircleQuestion} size={18}/>{"'!compact && '"'Помощь и поддержка'}</Button><div className=\"sidebar-account\"><span className=\"account-avatar\">АК</span>{"'!compact && <div><strong>Алексей Кузнецов</strong><small>Администратор</small></div>}</div></div>} renderContent={renderContent}/>
  <Modal open={modal !== null} onOpenChange={open => !open && setModal(null)} contentClassName="app-modal"><div className="modal-header"><Text variant="header-2">{modal === '"'new' ? 'Новый заказ' : modal === 'filters' ? 'Фильтры заказов' : modal === 'columns' ? 'Колонки таблицы' : modal === 'notifications' ? 'Уведомления' : 'Помощь и поддержка'}</Text><Button view=\"flat\" aria-label=\"Закрыть\" onClick={() => setModal(null)}><Icon data={Xmark} size={18}/></Button></div>
    {modal === 'new' && <form className=\"order-form\" onSubmit={addOrder}><p className=\"modal-description\">Создайте заказ — он появится в списке новых.</p><label>Покупатель<TextInput autoFocus size=\"l\" placeholder=\"Имя и фамилия\" value={form.name} onUpdate={v => setForm({...form, name: v})}/></label><label>Email<TextInput size=\"l\" type=\"email\" placeholder=\"name@example.com\" value={form.email} onUpdate={v => setForm({...form, email: v})}/></label><div className=\"form-row\"><label>Сумма, ₽<TextInput size=\"l\" type=\"number\" value={form.amount} onUpdate={v => setForm({...form, amount: v})} controlProps={{min: 1, step: '0.01'}}/></label><label>Товаров<TextInput size=\"l\" type=\"number\" value={form.items} onUpdate={v => setForm({...form, items: v})} controlProps={{min: 1}}/></label></div>{formError && <p className=\"form-error\">{formError}</p>}<div className=\"modal-actions\"><Button size=\"l\" view=\"outlined\" onClick={() => setModal(null)}>Отмена</Button><Button size=\"l\" view=\"action\" type=\"submit\">Создать заказ</Button></div></form>}
    {modal === 'filters' && <div className=\"order-form\"><p className=\"modal-description\">Показывайте только нужные вам заказы.</p><label>Оплата<Select size=\"l\" width=\"max\" value={[draftPayment]} onUpdate={v => setDraftPayment(v[0])} options={[{value: 'all', content: 'Любая оплата'}, {value: 'paid', content: 'Оплачен'}, {value: 'pending', content: 'Ожидает оплаты'}, {value: 'refunded', content: 'Возврат'}]}/></label><label>Минимальная сумма, ₽<TextInput size=\"l\" type=\"number\" value={draftAmount} onUpdate={setDraftAmount} placeholder=\"Например, 5000\" controlProps={{min: 0}}/></label><div className=\"modal-actions\"><Button size=\"l\" view=\"flat\" onClick={() => {setDraftPayment('all'); setDraftAmount('');}}>Сбросить</Button><Button size=\"l\" view=\"action\" onClick={() => {setPaymentFilter(draftPayment); setMinAmount(draftAmount); setModal(null);}}>Применить фильтры</Button></div></div>}
    {modal === 'columns' && <div className=\"order-form\"><p className=\"modal-description\">Выберите видимые колонки. Для изменения порядка перетащите заголовок в таблице.</p>{table.getAllLeafColumns().filter(c => "'!['"'select', 'actions'].includes(c.id)).map(c => <Checkbox key={c.id} checked={c.getIsVisible()} onUpdate={v => c.toggleVisibility(v)}>{String(c.columnDef.header)}</Checkbox>)}<Button size=\"l\" view=\"outlined\" onClick={() => {setColumnVisibility({}); setColumnOrder(['select', 'id', 'name', 'date', 'amount', 'status', 'payment', 'actions']);}}>Восстановить по умолчанию</Button><Button size=\"l\" view=\"action\" onClick={() => setModal(null)}>Готово</Button></div>}
    {modal === 'help' && <div className=\"support-content\"><span className=\"support-icon\"><Icon data={CircleQuestion} size={32}/></span><Text variant=\"subheader-3\">Давайте разберёмся вместе</Text><p>Выделяйте заказы чекбоксами, перетаскивайте заголовки колонок и нажимайте «По статусу», чтобы включить группировку. Нажмите на номер заказа, чтобы посмотреть подробности.</p><Button size=\"l\" view=\"action\" href=\"mailto:support@orbit.example\">Написать в поддержку</Button><small>support@orbit.example · Пн–Пт, 9:00–18:00</small></div>}
    {modal === 'notifications' && <div className=\"notifications-content\"><div className=\"notification-entry\"><span className=\"stat-icon violet\"><ShoppingBag width={18}/></span><div><strong>Есть новые заказы</strong><p>{orders.filter(o => o.status === 'new').length} заказов ожидают обработки</p><Button view=\"flat\" onClick={() => {setSection('orders'); setStatus('new'); setModal(null);}}>Посмотреть заказы<Icon data={ArrowRight} size={14}/></Button></div></div><div className=\"notification-entry\"><span className=\"stat-icon green\"><Check width={18}/></span><div><strong>Всё под контролем</strong><p>Данные магазина актуальны</p><small>Только что</small></div></div></div>}
  </Modal>
  <Modal open={detail "'!== null} onOpenChange={open => !open && setDetail(null)} contentClassName="app-modal">{detail && <><div className="modal-header"><Text variant="header-2">Заказ #{detail.id}</Text><Button view="flat" aria-label="Закрыть заказ" onClick={() => setDetail(null)}><Icon data={Xmark} size={18}/></Button></div><div className="order-detail"><StatusBadge status={detail.status}/><Customer order={detail}/><dl><div><dt>Дата оформления</dt><dd>{dateLabel(detail.date)}, {detail.time}</dd></div><div><dt>Количество товаров</dt><dd>{detail.items}</dd></div><div><dt>Способ оплаты</dt><dd>{detail.method}</dd></div><div><dt>Оплата</dt><dd><Payment value={detail.payment}/></dd></div><div className="detail-total"><dt>Сумма заказа</dt><dd>{money(detail.amount)}</dd></div></dl><Select size="l" width="max" label="Статус:" value={[detail.status]} onUpdate={v => changeStatus([detail.id], v[0] as Status)} options={Object.entries(statuses).map(([value, content]) => ({value, content}))}/><Button view="action" size="l" onClick={() => setDetail(null)}>Готово</Button></div></>}</Modal>
  {notice && <div className="toast" role="status"><span><Icon data={CircleCheck} size={20}/></span>{notice}<Button view="flat" aria-label="Закрыть уведомление" onClick={() => setNotice('"'')}><Icon data={Xmark} size={14}/></Button></div>}
  </>;
}
EOF"

